import type { UpdateTrack } from '../types/ipc/UpdateTrack';

/**
 * The update track THIS BUILD defaults to (#579).
 *
 * The one thing in Settings whose default cannot come from `defaultConfig`.
 * That snapshot is generated by `pnpm gen:ipc-types` on a developer machine and
 * therefore always says `"stable"`, but the Rust default is
 * `option_env!("STALAGMIGHT_CHANNEL")` (`config/types.rs`, `UpdateTrack::default`),
 * which the weekly workflow sets - so on a weekly build the real default is
 * `"weekly"`. Comparing against the snapshot there marks an untouched row as
 * changed and offers to "reset" it to a track the user never chose.
 *
 * `__APP_CHANNEL__` is the SAME build variable read by vite (see
 * `vite.config.ts`); the two are one build env mirrored across the language
 * boundary and must be changed together.
 *
 * Both reset paths go through here - the per-row reset in `GeneralSettings` and
 * the category-wide "Reset to Defaults" in `SettingsDialog` - because fixing
 * only the row left the header button staging `"stable"` on a weekly build.
 */
export function buildDefaultUpdateTrack(): UpdateTrack {
  return __APP_CHANNEL__ === 'weekly' ? 'weekly' : 'stable';
}
